     1→/**
     2→ * FreeWire Phase 9 — Contract Inferrer
     3→ *
     4→ * "사람이 contract를 직접 안 써도 된다"
     5→ *
     6→ * 노드의 subtype + goal text + 연결된 와이어 구조를 보고
     7→ * requires / ensures / produces / warns 를 자동으로 추론한다.
     8→ *
     9→ * 추론 방법:
    10→ *   1. Subtype 기반 기본 템플릿 (intent-spec의 defaults 확장)
    11→ *   2. Goal text NLP: 키워드 → facts 매핑
    12→ *   3. 구조 분석: 연결된 노드 조합 → 추가 facts
    13→ *   4. 이력 보정: 과거에 자주 필요했던 facts 추가
    14→ */
    15→
    16→'use strict';
    17→
    18→const { NODE_INTENT_DEFAULTS, parseGoalToFacts, wireFrom, wireTo } = require('./intent-spec');
    19→
    20→// ─── 추론 결과 ───────────────────────────────────────────────
    21→
    22→class InferredContract {
    23→  constructor({ requires, ensures, produces, warns, confidence, sources }) {
    24→    this.requires   = requires   ?? [];
    25→    this.ensures    = ensures    ?? [];
    26→    this.produces   = produces   ?? [];
    27→    this.warns      = warns      ?? [];
    28→    this.confidence = confidence ?? 0.7; // 0-1, 추론 신뢰도
    29→    this.sources    = sources    ?? [];  // ['subtype_template', 'goal_text', 'structure']
    30→  }
    31→}
    32→
    33→// ─── Contract Inferrer ──────────────────────────────────────
    34→
    35→class ContractInferrer {
    36→  constructor(history = null) {
    37→    this._history = history;
    38→  }
    39→
    40→  /**
    41→   * 단일 노드의 contract 추론
    42→   * @param {object} node        - 노드 정의
    43→   * @param {object[]} allNodes  - 전체 노드 배열 (구조 분석용)
    44→   * @param {object[]} wires     - 전체 와이어 배열
    45→   * @param {string} goalText    - 사용자 의도 텍스트
    46→   */
    47→  infer(node, allNodes = [], wires = [], goalText = '') {
    48→    const sources = [];
    49→    let requires = new Set();
    50→    let ensures  = new Set();
    51→    let produces = new Set();
    52→    let warns    = new Set();
    53→    let confidence = 0.5;
    54→
    55→    // 1) Subtype 기본 템플릿
    56→    const template = NODE_INTENT_DEFAULTS[node.subtype];
    57→    if (template?.contract) {
    58→      for (const f of (template.contract.requires ?? []))  requires.add(f);
    59→      for (const f of (template.contract.ensures  ?? []))  ensures.add(f);
    60→      for (const f of (template.contract.produces ?? []))  produces.add(f);
    61→      for (const f of (template.contract.warns    ?? []))  warns.add(f);
    62→      confidence += 0.2;
    63→      sources.push('subtype_template');
    64→    }
    65→
    66→    // 2) 노드 props 분석
    67→    this._inferFromProps(node, requires, ensures, produces, warns);
    68→    sources.push('props_analysis');
    69→
    70→    // 3) Goal text 분석
    71→    if (goalText) {
    72→      const goalFacts = parseGoalToFacts(goalText);
    73→      const relevant  = this._filterRelevantFacts(node.subtype, goalFacts);
    74→      for (const f of relevant) produces.add(f);
    75→      if (relevant.length > 0) {
    76→        confidence += 0.1;
    77→        sources.push('goal_text');
    78→      }
    79→    }
    80→
    81→    // 4) 연결 구조 분석
    82→    const structureFacts = this._inferFromStructure(node, allNodes, wires);
    83→    for (const f of structureFacts.requires) requires.add(f);
    84→    for (const f of structureFacts.produces) produces.add(f);
    85→    for (const f of structureFacts.warns)    warns.add(f);
    86→    if (structureFacts.requires.length + structureFacts.produces.length > 0) {
    87→      confidence += 0.1;
    88→      sources.push('structure');
    89→    }
    90→
    91→    // 5) 이력 보정 (있는 경우)
    92→    if (this._history) {
    93→      const histFacts = this._inferFromHistory(node.subtype);
    94→      for (const f of histFacts) warns.add(f);
    95→      if (histFacts.length > 0) {
    96→        confidence = Math.min(confidence + 0.05, 1.0);
    97→        sources.push('history');
    98→      }
    99→    }
   100→
   101→    return new InferredContract({
   102→      requires: [...requires],
   103→      ensures:  [...ensures],
   104→      produces: [...produces],
   105→      warns:    [...warns],
   106→      confidence: Math.min(confidence, 1.0),
   107→      sources,
   108→    });
   109→  }
   110→
   111→  /**
   112→   * 그래프 전체 nodes에 contract 자동 주입
   113→   * contract가 없거나 비어있는 노드에만 적용
   114→   */
   115→  inferAll(nodes, wires, goalText = '') {
   116→    const nodesArr = [...nodes.values()].map(v => v.def ?? v);
   117→    const wiresArr = [...wires.values()];
   118→    const results  = new Map();
   119→
   120→    for (const node of nodesArr) {
   121→      const hasContract = node.contract &&
   122→        (node.contract.requires?.length > 0 || node.contract.produces?.length > 0);
   123→
   124→      if (!hasContract) {
   125→        const inferred = this.infer(node, nodesArr, wiresArr, goalText);
   126→        results.set(node.id, inferred);
   127→      }
   128→    }
   129→
   130→    return results; // Map<nodeId, InferredContract>
   131→  }
   132→
   133→  // ─── 내부 추론 로직 ──────────────────────────────────────
   134→
   135→  _inferFromProps(node, requires, ensures, produces, warns) {
   136→    const props = node.props ?? {};
   137→    const type  = node.subtype;
   138→
   139→    if (type === 'input') {
   140→      if (props.type === 'email')    produces.add('form.email.filled');
   141→      if (props.type === 'password') produces.add('form.password.filled');
   142→      if (props.type === 'text')     produces.add('data.available');
   143→      if (props.required)            ensures.add('form.field.required');
   144→    }
   145→
   146→    if (type === 'button') {
   147→      const label = (props.label ?? '').toLowerCase();
   148→      if (/로그인|login/.test(label))   produces.add('auth.initiated');
   149→      if (/제출|submit/.test(label))    produces.add('form.submitted');
   150→      if (/검색|search/.test(label))    produces.add('search.initiated');
   151→      if (/증가|[+]|inc/.test(label))   produces.add('counter.incremented');
   152→      if (/감소|[-]|dec/.test(label))   produces.add('counter.decremented');
   153→      if (/추가|add/.test(label))       produces.add('item.added');
   154→      if (/삭제|remove|del/.test(label))produces.add('item.removed');
   155→    }
   156→
   157→    if (type === 'state') {
   158→      const name = (props.name ?? '').toLowerCase();
   159→      if (/count|카운트/.test(name))   produces.add('counter.state.available');
   160→      if (/user|사용자/.test(name))    produces.add('user.state.available');
   161→      if (/list|목록/.test(name))      produces.add('list.state.available');
   162→      produces.add('state.available');
   163→    }
   164→
   165→    if (type === 'handler') {
   166→      const name = (props.name ?? '').toLowerCase();
   167→      if (/login|로그인/.test(name))   ensures.add('auth.handler.ready');
   168→      if (/submit|제출/.test(name))    ensures.add('form.handler.ready');
   169→      requires.add('action.triggered');
   170→    }
   171→
   172→    if (type === 'text') {
   173→      warns.add('state.bound'); // 텍스트는 보통 상태와 연결돼야 함
   174→    }
   175→
   176→    if (type === 'container' || type === 'card') {
   177→      ensures.add('layout.structured');
   178→    }
   179→  }
   180→
   181→  _filterRelevantFacts(subtype, goalFacts) {
   182→    // subtype과 관련 있을 법한 goal facts만 필터
   183→    const SUBTYPE_FACT_AFFINITY = {
   184→      button:    ['auth.initiated', 'form.submitted', 'search.initiated', 'counter.incremented'],
   185→      input:     ['form.email.filled', 'form.password.filled', 'data.available'],
   186→      state:     ['state.bound', 'counter.state.available'],
   187→      handler:   ['auth.handler.ready', 'form.handler.ready', 'action.handler.present'],
   188→      text:      ['state.bound', 'data.displayed'],
   189→      container: ['layout.structured'],
   190→    };
   191→
   192→    const affinities = new Set(SUBTYPE_FACT_AFFINITY[subtype] ?? []);
   193→    return goalFacts.filter(f => affinities.has(f));
   194→  }
   195→
   196→  _inferFromStructure(node, allNodes, wires) {
   197→    const requires = [];
   198→    const produces = [];
   199→    const warns    = [];
   200→
   201→    // 이 노드의 입력 연결
   202→    const inputWires  = wires.filter(w => wireTo(w) === node.id);
   203→    // 이 노드의 출력 연결
   204→    const outputWires = wires.filter(w => wireFrom(w) === node.id);
   205→
   206→    // 연결된 소스 노드들의 subtype
   207→    const sourceSubs = inputWires
   208→      .map(w => allNodes.find(n => n.id === wireFrom(w))?.subtype)
   209→      .filter(Boolean);
   210→
   211→    // 연결된 타겟 노드들의 subtype
   212→    const targetSubs = outputWires
   213→      .map(w => allNodes.find(n => n.id === wireTo(w))?.subtype)
   214→      .filter(Boolean);
   215→
   216→    // 구조 패턴 기반 facts 추론
   217→    if (node.subtype === 'handler') {
   218→      if (sourceSubs.includes('button')) produces.push('ui.button.connected');
   219→      if (targetSubs.includes('state'))  produces.push('state.mutation.possible');
   220→    }
   221→
   222→    if (node.subtype === 'state') {
   223→      if (targetSubs.includes('text'))   produces.push('state.bound');
   224→      if (sourceSubs.includes('handler'))requires.push('action.handler.present');
   225→    }
   226→
   227→    if (node.subtype === 'button') {
   228→      if (!sourceSubs.includes('handler') && allNodes.some(n => n.subtype === 'handler')) {
   229→        warns.push('ui.button.connected');
   230→      }
   231→    }
   232→
   233→    return { requires, produces, warns };
   234→  }
   235→
   236→  _inferFromHistory(subtype) {
   237→    if (!this._history) return [];
   238→
   239→    // 이 subtype에서 자주 경고됐던 facts
   240→    const top = this._history.topViolations(10);
   241→    return top
   242→      .filter(v => v.pattern.startsWith(`${subtype}:`))
   243→      .map(v => v.pattern.split(':')[1])
   244→      .filter(Boolean);
   245→  }
   246→}
   247→
   248→// ─── 인라인 사용 헬퍼 ───────────────────────────────────────
   249→
   250→/**
   251→ * 노드에 inferred contract를 머지
   252→ * 기존 contract를 유지하면서 비어있는 필드만 채움
   253→ */
   254→function mergeInferredContract(node, inferred) {
   255→  const existing = node.contract ?? {};
   256→  return {
   257→    ...node,
   258→    contract: {
   259→      requires: existing.requires?.length ? existing.requires : inferred.requires,
   260→      ensures:  existing.ensures?.length  ? existing.ensures  : inferred.ensures,
   261→      produces: existing.produces?.length ? existing.produces : inferred.produces,
   262→      warns:    existing.warns?.length    ? existing.warns    : inferred.warns,
   263→      _inferred: true,
   264→      _confidence: inferred.confidence,
   265→      _sources:    inferred.sources,
   266→    },
   267→  };
   268→}
   269→
   270→module.exports = { ContractInferrer, InferredContract, mergeInferredContract };
   271→

