     1→/**
     2→ * FreeWire Phase 7 — Intent Evaluator
     3→ *
     4→ * "버튼이 렌더되나?" 가 아니라
     5→ * "인증이 시작될 수 있는 상태인가?" 를 판단한다.
     6→ *
     7→ * 세 가지를 검사한다:
     8→ *   1. Structural Check  — 필요한 노드/와이어가 존재하는가?
     9→ *   2. Contract Check    — 각 노드의 requires가 충족되는가?
    10→ *   3. Goal Check        — 목표 Facts가 그래프에서 생산 가능한가?
    11→ */
    12→
    13→'use strict';
    14→
    15→const { NODE_INTENT_DEFAULTS, parseGoalToFacts, wireFrom, wireTo } = require('./intent-spec');
    16→
    17→// ─── 위반 구조 ─────────────────────────────────────────────────
    18→
    19→class ContractViolation {
    20→  constructor({ nodeId, nodeLabel, type, fact, message, severity, repairHint }) {
    21→    this.nodeId    = nodeId;
    22→    this.nodeLabel = nodeLabel;
    23→    this.type      = type;       // 'requires' | 'ensures' | 'goal' | 'structural' | 'warning'
    24→    this.fact      = fact;       // 위반된 fact
    25→    this.message   = message;    // 사람이 읽을 수 있는 설명
    26→    this.severity  = severity;   // 'error' | 'warning'
    27→    this.repairHint= repairHint; // 수정 방향 힌트
    28→  }
    29→
    30→  toString() {
    31→    return `[${this.severity.toUpperCase()}] ${this.nodeLabel}: ${this.message}`;
    32→  }
    33→}
    34→
    35→// ─── Intent Evaluator ──────────────────────────────────────────
    36→
    37→class IntentEvaluator {
    38→  /**
    39→   * @param {Map}    nodes  - editor.nodes (NodeView Map)
    40→   * @param {Map}    wires  - editor.wires (wire Map)
    41→   * @param {string} goal   - 사용자 원래 의도 ("로그인 폼 만들어줘")
    42→   */
    43→  evaluate(nodes, wires, goal = '') {
    44→    const nodesArr = this._extractDefs(nodes);
    45→    const wiresArr = [...wires.values()];
    46→
    47→    const violations = [];
    48→    const satisfiedFacts = new Set();
    49→
    50→    // 1) 구조 검사: 빈 그래프
    51→    if (nodesArr.length === 0) {
    52→      violations.push(new ContractViolation({
    53→        nodeId: null, nodeLabel: '그래프',
    54→        type: 'structural', fact: 'graph.nonempty',
    55→        message: '노드가 없습니다. UI를 만들려면 노드를 추가하세요.',
    56→        severity: 'error', repairHint: 'add_node',
    57→      }));
    58→      return this._buildReport(violations, satisfiedFacts, goal, nodesArr, wiresArr);
    59→    }
    60→
    61→    // 2) 각 노드의 Contract 검사
    62→    for (const node of nodesArr) {
    63→      const contract = node.contract ?? this._getDefaultContract(node.subtype);
    64→      const producedByConnected = this._factsProducedByInputs(node, nodesArr, wiresArr);
    65→
    66→      // requires 검사
    67→      for (const req of (contract.requires ?? [])) {
    68→        if (!producedByConnected.has(req) && !satisfiedFacts.has(req)) {
    69→          violations.push(new ContractViolation({
    70→            nodeId: node.id, nodeLabel: node.label ?? node.subtype,
    71→            type: 'requires', fact: req,
    72→            message: `"${req}" 조건이 필요하지만 연결된 노드가 제공하지 않습니다.`,
    73→            severity: 'error',
    74→            repairHint: `connect_${req.split('.')[0]}`,
    75→          }));
    76→        }
    77→      }
    78→
    79→      // warns 검사 (권장)
    80→      for (const warn of (contract.warns ?? [])) {
    81→        if (!producedByConnected.has(warn)) {
    82→          violations.push(new ContractViolation({
    83→            nodeId: node.id, nodeLabel: node.label ?? node.subtype,
    84→            type: 'warning', fact: warn,
    85→            message: `"${warn}" 조건이 충족되면 더 완전한 UI가 됩니다.`,
    86→            severity: 'warning',
    87→            repairHint: `enhance_${warn.split('.')[0]}`,
    88→          }));
    89→        }
    90→      }
    91→
    92→      // 이 노드가 produces하는 facts 수집
    93→      for (const p of (contract.produces ?? [])) satisfiedFacts.add(p);
    94→      for (const e of (contract.ensures ?? []))  satisfiedFacts.add(e);
    95→    }
    96→
    97→    // 3) 특수 구조 검사
    98→    this._checkButtonHandlerConnections(nodesArr, wiresArr, violations);
    99→    this._checkStateBindings(nodesArr, wiresArr, violations, satisfiedFacts);
   100→    this._checkOrphanNodes(nodesArr, wiresArr, violations);
   101→
   102→    // 4) Goal Facts 검사
   103→    if (goal) {
   104→      const goalFacts = parseGoalToFacts(goal);
   105→      for (const gf of goalFacts) {
   106→        if (!satisfiedFacts.has(gf)) {
   107→          violations.push(new ContractViolation({
   108→            nodeId: null, nodeLabel: '목표',
   109→            type: 'goal', fact: gf,
   110→            message: `목표 달성에 필요한 "${gf}"가 현재 그래프에서 생산되지 않습니다.`,
   111→            severity: 'error',
   112→            repairHint: `goal_${gf.replace(/\./g, '_')}`,
   113→          }));
   114→        }
   115→      }
   116→    }
   117→
   118→    return this._buildReport(violations, satisfiedFacts, goal, nodesArr, wiresArr);
   119→  }
   120→
   121→  // ─── 특수 구조 검사들 ──────────────────────────────────────
   122→
   123→  _checkButtonHandlerConnections(nodesArr, wiresArr, violations) {
   124→    const buttons  = nodesArr.filter(n => n.subtype === 'button');
   125→    const handlers = nodesArr.filter(n => n.subtype === 'handler');
   126→
   127→    for (const btn of buttons) {
   128→      // 버튼의 onClick 포트(인덱스 1)에 핸들러가 연결됐는지 확인
   129→      const connected = wiresArr.some(w =>
   130→        wireTo(w) === btn.id && (w.tp ?? w.toPort ?? w.to?.portId) === 1
   131→      );
   132→      if (!connected && handlers.length > 0) {
   133→        violations.push(new ContractViolation({
   134→          nodeId: btn.id, nodeLabel: btn.label ?? '버튼',
   135→          type: 'structural', fact: 'ui.button.connected',
   136→          message: `버튼 "${btn.props?.label ?? btn.id}"에 클릭 핸들러가 연결되지 않았습니다. 클릭해도 아무 일도 일어나지 않습니다.`,
   137→          severity: 'error',
   138→          repairHint: 'wire_handler_to_button',
   139→        }));
   140→      }
   141→    }
   142→
   143→    // 핸들러가 아예 없는데 버튼은 있는 경우
   144→    if (buttons.length > 0 && handlers.length === 0) {
   145→      violations.push(new ContractViolation({
   146→        nodeId: null, nodeLabel: '그래프',
   147→        type: 'structural', fact: 'action.handler.present',
   148→        message: `버튼이 ${buttons.length}개 있지만 이벤트 핸들러가 없습니다. 버튼 클릭이 동작하지 않습니다.`,
   149→        severity: 'error',
   150→        repairHint: 'add_handler_node',
   151→      }));
   152→    }
   153→  }
   154→
   155→  _checkStateBindings(nodesArr, wiresArr, violations, satisfiedFacts) {
   156→    const stateNodes = nodesArr.filter(n => n.subtype === 'state');
   157→    const textNodes  = nodesArr.filter(n => n.subtype === 'text');
   158→
   159→    for (const st of stateNodes) {
   160→      // state가 text/컴포넌트에 연결됐는지
   161→      const hasOutput = wiresArr.some(w => wireFrom(w) === st.id);
   162→      if (!hasOutput && textNodes.length > 0) {
   163→        violations.push(new ContractViolation({
   164→          nodeId: st.id, nodeLabel: st.label ?? '상태',
   165→          type: 'structural', fact: 'state.bound',
   166→          message: `상태 "${st.props?.name ?? st.id}"가 UI에 바인딩되지 않았습니다. 상태가 변해도 화면이 갱신되지 않습니다.`,
   167→          severity: 'warning',
   168→          repairHint: 'wire_state_to_display',
   169→        }));
   170→      } else if (hasOutput) {
   171→        satisfiedFacts.add('state.bound');
   172→      }
   173→    }
   174→  }
   175→
   176→  _checkOrphanNodes(nodesArr, wiresArr, violations) {
   177→    if (nodesArr.length < 3) return; // 소규모 그래프는 고아 체크 생략
   178→
   179→    for (const node of nodesArr) {
   180→      if (node.type !== 'component') continue;
   181→      const hasAnyWire = wiresArr.some(w =>
   182→        wireFrom(w) === node.id || wireTo(w) === node.id
   183→      );
   184→      if (!hasAnyWire) {
   185→        violations.push(new ContractViolation({
   186→          nodeId: node.id, nodeLabel: node.label ?? node.subtype,
   187→          type: 'structural', fact: 'node.connected',
   188→          message: `노드 "${node.label ?? node.id}"가 다른 노드와 연결되지 않았습니다. 고립된 상태입니다.`,
   189→          severity: 'warning',
   190→          repairHint: 'connect_orphan',
   191→        }));
   192→      }
   193→    }
   194→  }
   195→
   196→  // ─── 헬퍼 ────────────────────────────────────────────────────
   197→
   198→  _extractDefs(nodes) {
   199→    return [...nodes.values()].map(v => v.def ?? v);
   200→  }
   201→
   202→  _getDefaultContract(subtype) {
   203→    return NODE_INTENT_DEFAULTS[subtype]?.contract ?? { requires: [], ensures: [], produces: [], warns: [] };
   204→  }
   205→
   206→  /**
   207→   * 이 노드의 입력 포트에 연결된 노드들이 produces하는 facts
   208→   */
   209→  _factsProducedByInputs(node, nodesArr, wiresArr) {
   210→    const produced = new Set();
   211→    const inputWires = wiresArr.filter(w => wireTo(w) === node.id);
   212→
   213→    for (const wire of inputWires) {
   214→      const sourceNode = nodesArr.find(n => n.id === wireFrom(wire));
   215→      if (!sourceNode) continue;
   216→      const contract = sourceNode.contract ?? this._getDefaultContract(sourceNode.subtype);
   217→      for (const p of (contract.produces ?? [])) produced.add(p);
   218→      for (const e of (contract.ensures  ?? [])) produced.add(e);
   219→    }
   220→
   221→    return produced;
   222→  }
   223→
   224→  _buildReport(violations, satisfiedFacts, goal, nodesArr, wiresArr) {
   225→    const errors   = violations.filter(v => v.severity === 'error');
   226→    const warnings = violations.filter(v => v.severity === 'warning');
   227→
   228→    const totalFacts     = goal ? parseGoalToFacts(goal) : [];
   229→    const satisfiedGoals = totalFacts.filter(f => satisfiedFacts.has(f));
   230→    const score = totalFacts.length > 0
   231→      ? Math.round((satisfiedGoals.length / totalFacts.length) * 100)
   232→      : (errors.length === 0 ? 100 : 0);
   233→
   234→    return {
   235→      score,                    // 0-100 — 의도 충족 점수
   236→      passed: errors.length === 0,
   237→      errors,
   238→      warnings,
   239→      violations,
   240→      satisfiedFacts: [...satisfiedFacts],
   241→      missingFacts: totalFacts.filter(f => !satisfiedFacts.has(f)),
   242→      summary: this._buildSummary(score, errors, warnings, nodesArr, wiresArr),
   243→    };
   244→  }
   245→
   246→  _buildSummary(score, errors, warnings, nodesArr, wiresArr) {
   247→    if (errors.length === 0 && warnings.length === 0) {
   248→      return `✅ 의도 100% 충족 — 모든 계약이 만족됩니다`;
   249→    }
   250→    const parts = [];
   251→    if (score < 100) parts.push(`의도 충족률: ${score}%`);
   252→    if (errors.length)   parts.push(`오류 ${errors.length}개`);
   253→    if (warnings.length) parts.push(`경고 ${warnings.length}개`);
   254→    parts.push(`노드 ${nodesArr.length}개 / 와이어 ${wiresArr.length}개`);
   255→    return parts.join(' | ');
   256→  }
   257→}
   258→
   259→module.exports = { IntentEvaluator, ContractViolation };
   260→

