     1→/**
     2→ * FreeWire Phase 7 — Self-Correct Loop
     3→ *
     4→ * 루프가 닫힌다.
     5→ *
     6→ * 생성 → 평가 → [score < 100?] → 수리 → 재평가 → ...
     7→ *         ↑__________________________________|
     8→ *
     9→ * 이 루프가 돌 때 사람은 개입하지 않는다.
    10→ * 시스템이 스스로 의도에 근접해간다.
    11→ */
    12→
    13→'use strict';
    14→
    15→const { IntentEvaluator } = require('./evaluator');
    16→const { RepairEngine }    = require('./repair-engine');
    17→
    18→class SelfCorrectLoop {
    19→  constructor({ maxIterations = 3, targetScore = 85 } = {}) {
    20→    this.maxIterations = maxIterations;
    21→    this.targetScore   = targetScore;
    22→    this.evaluator     = new IntentEvaluator();
    23→    this.repair        = new RepairEngine();
    24→  }
    25→
    26→  /**
    27→   * 단 하나의 공개 메서드.
    28→   * 목표 텍스트와 그래프를 받아서, 자기 수정 루프를 돌린다.
    29→   *
    30→   * @param {string} goal    - 사용자 원래 의도
    31→   * @param {Map}    nodes   - 현재 노드 맵 (mutable)
    32→   * @param {Map}    wires   - 현재 와이어 맵 (mutable)
    33→   * @param {Function} nextId - ID 생성기
    34→   * @returns {LoopResult}
    35→   */
    36→  run(goal, nodes, wires, nextId = defaultNextId()) {
    37→    const trace = [];
    38→    let iteration = 0;
    39→    let lastReport = null;
    40→
    41→    while (iteration < this.maxIterations) {
    42→      iteration++;
    43→
    44→      // 1) 평가
    45→      const report = this.evaluator.evaluate(nodes, wires, goal);
    46→      lastReport = report;
    47→
    48→      trace.push({
    49→        iteration,
    50→        score:      report.score,
    51→        errors:     report.errors.length,
    52→        warnings:   report.warnings.length,
    53→        patches:    [],
    54→        summary:    report.summary,
    55→      });
    56→
    57→      // 목표 달성
    58→      if (report.passed && report.score >= this.targetScore) {
    59→        break;
    60→      }
    61→
    62→      // 오류 없음 (경고만)
    63→      if (report.errors.length === 0) {
    64→        break;
    65→      }
    66→
    67→      // 점수가 이전과 동일하면 스태그네이션 → 무한 루프 방지
    68→      if (iteration > 1 && report.score === trace[trace.length - 2]?.score) {
    69→        break;
    70→      }
    71→
    72→      // 2) 수리 패치 생성
    73→      const patches = this.repair.suggest(report.violations, nodes, wires);
    74→      if (patches.length === 0) break; // 수리 방법 없음
    75→
    76→      // 3) 패치 적용
    77→      const { applied } = this.repair.applyPatches(patches, nodes, wires, nextId);
    78→      trace[trace.length - 1].patches = applied.map(p => ({
    79→        type: p.type, description: p.description, confidence: p.confidence,
    80→      }));
    81→
    82→      if (applied.length === 0) break; // 아무것도 적용 안 됨 (무한루프 방지)
    83→    }
    84→
    85→    return {
    86→      goal,
    87→      iterations:    iteration,
    88→      converged:     lastReport?.passed ?? false,
    89→      finalScore:    lastReport?.score  ?? 0,
    90→      trace,
    91→      finalReport:   lastReport,
    92→      improved:      trace.length > 1
    93→        ? (trace[trace.length - 1].score > trace[0].score)
    94→        : false,
    95→    };
    96→  }
    97→}
    98→
    99→// ─── 단일 평가만 (루프 없이) ────────────────────────────────────
   100→
   101→function evaluateOnce(goal, nodes, wires) {
   102→  const evaluator = new IntentEvaluator();
   103→  return evaluator.evaluate(nodes, wires, goal);
   104→}
   105→
   106→// ─── ID 생성기 팩토리 ───────────────────────────────────────────
   107→
   108→function defaultNextId() {
   109→  let ctr = Date.now();
   110→  return () => `rc-${ctr++}`;
   111→}
   112→
   113→module.exports = { SelfCorrectLoop, evaluateOnce, defaultNextId };
   114→

